import 'package:flutter/material.dart'; import '../services/auth_service.dart';
class ProfileScreen extends StatelessWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Profile')),body:FutureBuilder(future:AuthService().profile(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final p=s.data!;return Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.account_circle,size:72),Text(p.fullName,style:Theme.of(c).textTheme.headlineSmall),Text(AuthService().currentUser?.email??''),const SizedBox(height:24),const Text('iBantay is a school research prototype. It does not contact emergency authorities unless your researchers configure an official integration.'),const Spacer(),FilledButton.tonalIcon(onPressed:()=>AuthService().signOut(),icon:const Icon(Icons.logout),label:const Text('Logout'))]));}));}
